package agent
import("context";"fmt";"strings")
type LayerHealth struct{LayerID string;Healthy bool;Reason string};type HealthChecker interface{Check(context.Context)error}
func CheckLayer(ctx context.Context,layer Layer,checker HealthChecker)LayerHealth{layerID:=strings.TrimSpace(layer.ID);if layerID==""{return LayerHealth{Reason:"layer id is required"}};if len(layerID)>256{return LayerHealth{Reason:"layer id is too large"}};if ctx==nil{return LayerHealth{LayerID:layerID,Reason:"context is required"}};if err:=ctx.Err();err!=nil{return LayerHealth{LayerID:layerID,Reason:err.Error()}};if checker==nil{return LayerHealth{LayerID:layerID,Healthy:false,Reason:"health checker unavailable"}};if err:=checker.Check(ctx);err!=nil{reason:=strings.TrimSpace(err.Error());if len(reason)>1024{reason=reason[:1024]};return LayerHealth{LayerID:layerID,Healthy:false,Reason:reason}};return LayerHealth{LayerID:layerID,Healthy:true,Reason:fmt.Sprintf("layer %s healthy",layerID)}}
